{
  "document_kind": "excerpt_note",
  "report_markdown": "ENTWURF\n\n**Auszug aus Äußerung einer Person:**\n- Beschreibt starkes Bluten und einen Sprung (möglicherweise Sturz oder Suizidversuch).\n- Äußert Zweifel an der Überlebenschance: „Das kann man doch gar nicht überleben, oder Herr Doktor, wird er überleben.“\n- Äußert Schuldgefühle: „Ich fühle mich so schuldig.“",
  "facts": [
    {
      "category": "Symptome",
      "claim": "Es gab starkes Bluten.",
      "evidence_quotes": [
        "er hat wahnsinnig geblutet"
      ]
    },
    {
      "category": "Ereignis",
      "claim": "Es gab einen Sprung.",
      "evidence_quotes": [
        "dann noch der Sprung"
      ]
    },
    {
      "category": "Prognosefrage",
      "claim": "Die sprechende Person bezweifelt, dass die betroffene Person überleben kann.",
      "evidence_quotes": [
        "Das kann man doch gar nicht überleben, oder Herr Doktor, wird er überleben"
      ]
    },
    {
      "category": "psychische Belastung",
      "claim": "Die sprechende Person fühlt sich schuldig.",
      "evidence_quotes": [
        "Ich fühle mich so schuldig"
      ]
    }
  ],
  "uncertainties": [
    "Unklar, ob der Sprung ein Suizidversuch, Unfall oder anderes Ereignis war.",
    "Unklar, um welche Person es sich handelt (wer geblutet hat, wer gesprungen ist).",
    "Unklar, ob die betroffene Person männlich ist (Verwendung von 'er').",
    "Unklar, ob das Ereignis real oder hypothetisch beschrieben wird.",
    "Unklar, ob medizinische Versorgung erfolgt ist oder wer 'Herr Doktor' ist."
  ]
}
